48	// runCoreList fetches a slice via fn and renders it as an aligned table
49	// (default) or the raw wire JSON (--json). headers names the columns; row
50	// maps one item to its cells in the same order. The human view keeps the
51	// output actionable — only the columns a person acts on — while --json
52	// preserves the full model for scripting.
53	func runCoreList[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
54		return runCore(cmd, renderCoreList(cmd, headers, row, fn))
55	}
56	
57	// runCoreListForCluster is runCoreList for a resource-provider command (see
58	// runCoreForCluster): identical table/JSON rendering, but dialing the core that
59	// fronts clusterHost rather than the active context.
60	func runCoreListForCluster[T any](cmd *cobra.Command, clusterHost string, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
61		return runCoreForCluster(cmd, clusterHost, renderCoreList(cmd, headers, row, fn))
62	}
63	
64	// renderCoreList builds the run-function shared by runCoreList and
65	// runCoreListForCluster: fetch via fn, then render as a table (default) or raw
66	// JSON (--json). Kept separate from the client-selection so the two list
67	// variants differ only in which core they dial.
68	func renderCoreList[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) func(context.Context, *coreapi.Client) error {
69		return func(ctx context.Context, c *coreapi.Client) error {
70			items, err := fn(ctx, c)
71			if err != nil {
72				return err
73			}
74			if jsonRequested(cmd) {
75				return printJSON(cmd.OutOrStdout(), items)
76			}
77			if len(items) == 0 {
78				fmt.Fprintln(cmd.ErrOrStderr(), "(none)")
79				return nil
80			}
81			return printTable(cmd.OutOrStdout(), headers, items, row)
82		}
83	}
84	
85	// runCoreObject fetches a single value via fn and renders it as a vertical
86	// field/value list (default) or raw JSON (--json), reusing the same column
87	// definition as the matching list view.
88	func runCoreObject[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) error {
89		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
90			item, err := fn(ctx, c)
91			if err != nil {
92				return err
93			}
94			if jsonRequested(cmd) {
95				return printJSON(cmd.OutOrStdout(), item)
96			}
97			return printFields(cmd.OutOrStdout(), headers, row(*item))
98		})
99	}
100	
101	// tableStyles holds the foreground styles for the human table/field views,
102	// matching the activity/session palette: gray ("8") for headers and
103	// secondary cells, white ("7") for the primary (first-column) value. When
104	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
105	// styles are no-ops and output is plain.
106	type tableStyles struct {
107		enabled bool
108		header  lipgloss.Style
109		primary lipgloss.Style
110		cell    lipgloss.Style
111	}
112	
113	func newTableStyles(w io.Writer) tableStyles {
114		if !shouldUseColor(w) {
115			return tableStyles{}
116		}
117		return tableStyles{
118			enabled: true,
119			header:  lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true),
120			primary: lipgloss.NewStyle().Foreground(lipgloss.Color("7")),
121			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
122		}
123	}
124	
125	// style applies s to text only when color is enabled; otherwise it returns
126	// text unchanged so padding math and plain output stay correct.
127	func (t tableStyles) style(s lipgloss.Style, text string) string {
128		if !t.enabled {
129			return text
130		}
131		return s.Render(text)
132	}
133	
134	// columnStyle picks the foreground for a data cell: the first column is the
135	// primary identifier (white), the rest are secondary (gray).
136	func (t tableStyles) columnStyle(col int) lipgloss.Style {
137		if col == 0 {
138			return t.primary
139		}
140		return t.cell
141	}
142	
143	// printTable writes headers plus one row per item, columns aligned on the
144	// plain-text widths so ANSI color codes don't throw off the layout (they're
145	// applied after padding). Callers handle the empty case.
146	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
147		st := newTableStyles(w)
148		rows := make([][]string, len(items))
149		for i, it := range items {
150			rows[i] = row(it)
151		}
152		widths := columnWidths(headers, rows)
153	
154		var b strings.Builder
155		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
156		for _, r := range rows {
157			writeTableRow(&b, r, widths, st.columnStyle, st)
158		}
159		if _, err := io.WriteString(w, b.String()); err != nil {
160			return fmt.Errorf("render table: %w", err)
161		}
162		return nil
163	}
164	
165	// printFields writes a single record as aligned "FIELD  value" lines: the
166	// label in header gray, the value in the same primary/secondary color the
167	// list view would give that column.
168	func printFields(w io.Writer, headers, values []string) error {
169		st := newTableStyles(w)
170		labelWidth := 0
171		for _, h := range headers {
172			if n := lipgloss.Width(h); n > labelWidth {
173				labelWidth = n
174			}
175		}
176		var b strings.Builder
177		for i, h := range headers {
178			var v string
179			if i < len(values) {
180				v = values[i]
181			}
182			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
183			b.WriteString(label)
184			b.WriteString("  ")
185			b.WriteString(st.style(st.columnStyle(i), v))
186			b.WriteByte('\n')
187		}
188		if _, err := io.WriteString(w, b.String()); err != nil {
189			return fmt.Errorf("render fields: %w", err)
190		}
191		return nil
192	}
193	
194	// columnWidths returns the max plain-text width of each column across the
195	// headers and all rows.
196	func columnWidths(headers []string, rows [][]string) []int {
197		widths := make([]int, len(headers))
198		for i, h := range headers {
199			widths[i] = lipgloss.Width(h)
200		}
201		for _, r := range rows {
202			for i, c := range r {
203				if i < len(widths) && lipgloss.Width(c) > widths[i] {
204					widths[i] = lipgloss.Width(c)
205				}
206			}
207		}
208		return widths
209	}
210	
211	// writeTableRow pads each cell to its column width on the plain text, then
212	// styles it — so alignment is computed before any ANSI codes are added.
213	// The final column isn't padded, avoiding trailing whitespace.
214	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
215		for i, c := range cells {
216			last := i == len(cells)-1
217			padded := c
218			if !last && i < len(widths) {
219				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
220			}
221			b.WriteString(st.style(styleFor(i), padded))
222			if !last {
223				b.WriteString("  ")
224			}
225		}
226		b.WriteByte('\n')
227	}
228	
229	// runCoreJSON runs fn against an authenticated control-plane client and
230	// prints its result as indented JSON. It owns the preamble every
231	// control-plane command shares: silence usage so input errors don't spam
232	// the usage block, build the client, and map an API error to a
233	// problem-detail SilentError. Commands supply only the call + the value to
234	// render.
235	func runCoreJSON(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) (any, error)) error {
236		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
237			out, err := fn(ctx, c)
238			if err != nil {
239				return err
240			}
241			return printJSON(cmd.OutOrStdout(), out)
242		})
243	}
244	
245	// activeCoreClient builds the control-plane client for active-context
246	// commands. A package-level seam (production wiring is coreapi.New) so
247	// command-level tests can point the whole command tree at an httptest server
248	// without standing up the auth/context/TLS stack.
249	var activeCoreClient = func(context.Context) (*coreapi.Client, error) { return coreapi.New() }
250	
251	// runCore is the variant for commands that don't render JSON (delete,
252	// revoke, remove): it runs the same preamble — silence usage, build
253	// client, map API errors — and leaves any success output to fn. The client
254	// dials the active context's core (coreapi.New); use runCoreForCluster for
255	// commands addressed at a specific cluster.
256	func runCore(cmd *cobra.Command, fn func(ctx context.Context, c *coreapi.Client) error) error {
257		return runCoreClient(cmd, activeCoreClient, fn)
258	}
259	
260	// runCoreForCluster is runCore for resource-provider commands addressed at a
261	// specific cluster (mirror create/remove, mirror collaborators add/remove/list):
262	// it dials the core that fronts clusterHost — discovered from the cluster's
263	// /.well-known/entire-cluster.json, authenticating with the matching local
264	// context — instead of the active context. So the command works on a cluster in
265	// a federation other than the active login, instead of failing with "unknown
266	// cluster_host". See coreapi.NewForCluster.
267	func runCoreForCluster(cmd *cobra.Command, clusterHost string, fn func(ctx context.Context, c *coreapi.Client) error) error {
268		return runCoreClient(cmd, func(ctx context.Context) (*coreapi.Client, error) {
269			return coreapi.NewForCluster(ctx, clusterHost)
270		}, fn)
271	}
272	
273	// runCoreClient owns the control-plane preamble shared by the active-context
274	// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
275	// opt into plain-HTTP token exchange if requested, build the client via
276	// newClient, run fn, and map API errors. The only difference between the two
277	// variants is which core newClient dials.
278	func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
279		cmd.SilenceUsage = true
280		// Opt into plain-HTTP token exchange before the client (and its lazily
281		// built token manager) is constructed — the manager freezes the
282		// setting on first use.
283		if insecureHTTPRequested(cmd) {
284			auth.EnableInsecureHTTP()
285		}
286		client, err := newClient(cmd.Context())
287		if err != nil {
288			return fmt.Errorf("connect to Entire control plane: %w", err)
289		}
290		if err := fn(cmd.Context(), client); err != nil {
291			return renderCoreError(err)
292		}
293		return nil
294	}
295	
296	// markRequired marks one or more flags required, panicking if a name
297	// doesn't exist — that can only happen from a typo at wiring time, never
298	// at runtime, so a panic surfaces the bug immediately rather than letting
299	// a "required" flag silently not be enforced.
300	func markRequired(cmd *cobra.Command, names ...string) {
301		for _, name := range names {
302			if err := cmd.MarkFlagRequired(name); err != nil {
303				panic(fmt.Sprintf("mark flag %q required: %v", name, err))
304			}
305		}
306	}
307	
308	// renderCoreError converts a Core API error into the server's
309	// problem-detail message (so users see "organization name already taken"
310	// rather than ogen's decode-wrapped string), falling back to the raw error
311	// for transport/local failures. It returns a plain error, not a
312	// SilentError: main.go prints plain errors, and runCore has already set
313	// SilenceUsage, so the message reaches the user without a usage dump. (A
314	// SilentError here would be swallowed — main.go skips printing those —
315	// leaving e.g. a 409 conflict with no output.)
316	func renderCoreError(err error) error {
317		if err == nil {
318			return nil
319		}
320		if msg := coreapi.APIError(err); msg != "" {
321			return errors.New(msg)
322		}
323		return err
324	}
325	
326	// printJSON writes v as indented JSON to w — the --json view for list/get
327	// and the default for create commands that echo the new object.
328	func printJSON(w io.Writer, v any) error {
329		enc := json.NewEncoder(w)
330		enc.SetIndent("", "  ")
331		if err := enc.Encode(v); err != nil {
332			return fmt.Errorf("encode output: %w", err)
333		}
334		return nil
335	}
